INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Form 1120-S filing deadline for calendar-year S corp
(3, 'S Corporations', 'Cascade Analytics Inc. is a calendar-year S corporation. The company wants to know its federal income tax return filing deadline for 2026. By what date must Cascade file Form 1120-S without an extension?', '["March 15, 2027", "April 15, 2027", "September 15, 2027", "March 15, 2026"]'::jsonb, 0, 'Under IRC Section 6072(b), S corporations must file Form 1120-S by the 15th day of the third month after the close of the tax year. For calendar-year S corporations, this means March 15 of the following year. April 15 is the individual return due date under Section 6072(a), not the S corporation filing deadline.', 'medium', 2),

-- Q2: medium / L2 — ESBT taxation at highest individual rate
(3, 'S Corporations', 'An electing small business trust (ESBT) holds shares in Lakewood Corp, an S corporation. Lakewood passes through $80,000 of ordinary business income to the ESBT in 2026. At what tax rate is the S corporation income portion of the ESBT taxed?', '["The trust''s graduated rate based on taxable income brackets", "The highest individual marginal tax rate of 37%", "The corporate flat rate of 21%", "The capital gains rate of 20%"]'::jsonb, 1, 'Under IRC Section 641(c), the S corporation income portion of an ESBT is taxed at the highest individual marginal rate (currently 37%), not at graduated trust rates. This special rule prevents income splitting through ESBT structures. Graduated trust rates apply to the non-S-corporation portion of the trust''s income, not to the S corporation pass-through.', 'medium', 2),

-- Q3: medium / L3 — Grantor trust: grantor counted as shareholder
(3, 'S Corporations', 'Donovan creates a revocable living trust and transfers all shares of Summit Corp, an S corporation, into the trust. Under IRC Section 1361(c)(2), who is treated as the shareholder for purposes of the 100-shareholder limit and eligibility requirements?', '["The trust itself is counted as one shareholder", "The trustee is counted as the shareholder", "The grantor (Donovan) is counted as the shareholder", "Each trust beneficiary is counted as a separate shareholder"]'::jsonb, 2, 'Under IRC Section 1361(c)(2)(A)(i), a grantor trust is an eligible S corporation shareholder, and the deemed owner (grantor) is treated as the shareholder for counting and eligibility purposes. Since Donovan is a U.S. individual, Summit maintains its eligibility. The trust itself is not counted as a separate shareholder — the grantor is the deemed owner.', 'medium', 3),

-- Q4: hard / L4 — Mid-year voluntary revocation with specified future effective date
(3, 'S Corporations', 'Kendall Corp, a calendar-year S corporation, files a revocation on April 1, 2026, with shareholders holding 60% of the stock consenting. The revocation specifies July 1, 2026, as the effective date. Evaluate how Kendall''s 2026 tax year is divided and what returns must be filed.', '["The revocation is effective January 1, 2027, because it was filed after March 15", "The revocation fails because only 60% of shareholders consented instead of the required two-thirds", "The revocation is effective January 1, 2026, retroactive to the beginning of the year", "The revocation is effective July 1, 2026, creating a short S year (Jan 1–Jun 30) and a short C year (Jul 1–Dec 31)"]'::jsonb, 3, 'Under IRC Section 1362(d)(1)(C) and (D), a revocation may specify a prospective effective date, which controls and creates two short tax years. The July 1, 2026, date produces a short S year (Jan 1–Jun 30) and a short C year (Jul 1–Dec 31). Revocation requires more than 50% shareholder consent (not two-thirds), so the 60% threshold is met. Without the specified date, the April 1 filing would default to January 1, 2027.', 'hard', 4),

-- Q5: easy / L1 — S corp cannot generate its own E&P
(3, 'S Corporations', 'During which period can an S corporation generate its own earnings and profits (E&P)?', '["Any year in which the corporation has net income exceeding distributions", "Only years in which the corporation has passive investment income", "Years in which the corporation makes no distributions to shareholders", "An S corporation cannot generate its own E&P; it can only carry over E&P from C corporation years"]'::jsonb, 3, 'Under IRC Section 1371(c), an S corporation does not generate earnings and profits during S corporation years. Any E&P an S corporation carries is accumulated from prior C corporation years or inherited through a Section 381 transaction. This distinction matters because accumulated C corporation E&P triggers the excess net passive income tax under Section 1375 and affects distribution ordering.', 'easy', 1),

-- Q6: medium / L3 — Gain on loan repayment when debt basis was reduced by losses
(3, 'S Corporations', 'Mercer lent $40,000 directly to Ashford Corp, an S corporation. Prior-year losses reduced Mercer''s debt basis to $15,000. In 2026, Ashford repays the full $40,000 loan to Mercer without any intervening income allocations. What is the tax consequence to Mercer upon repayment?', '["No taxable income because the repayment is a return of loan principal", "$25,000 of capital gain on the repayment", "$25,000 of ordinary income on the repayment", "$40,000 of ordinary income on the repayment"]'::jsonb, 1, 'Under IRC Section 1367(b)(2) and Reg. 1.1367-2(e), when S corporation losses reduce a shareholder''s debt basis below face value, repayment in excess of adjusted debt basis triggers gain. Mercer''s debt basis is $15,000, so repayment of $40,000 produces $25,000 of gain, treated as capital gain because the note is a capital asset in the shareholder''s hands. Ordinary income treatment would apply only to interest, not principal repayment.', 'medium', 3),

-- Q7: hard / L4 — Net increase restores debt basis before stock basis (Reg. 1.1367-2)
(3, 'S Corporations', 'Franklin is the sole shareholder of Bedrock Corp, an S corporation. At the beginning of 2026, Franklin''s stock basis is $0 and debt basis is $10,000 (reduced from $25,000 by prior-year losses). During 2026, Bedrock reports $20,000 of ordinary income and makes no distributions. Evaluate how the $20,000 net increase is applied under Reg. 1.1367-2(c).', '["Stock basis increases to $20,000; debt basis remains at $10,000", "Stock basis increases to $5,000; debt basis is restored to $25,000", "Debt basis is first restored to $25,000 ($15,000 increase); then stock basis increases by $5,000", "Stock basis increases to $10,000; debt basis is restored to $20,000"]'::jsonb, 2, 'Under Reg. 1.1367-2(c), when a shareholder''s debt basis has been reduced by prior losses, any net increase for the year must first restore debt basis to its original face amount before increasing stock basis. Franklin''s debt basis was reduced from $25,000 to $10,000, so $15,000 of the $20,000 restores debt basis to $25,000, and the remaining $5,000 increases stock basis. This ordering prevents gain recognition on future loan repayments.', 'hard', 4),

-- Q8: easy / L1 — Cash contribution increases stock basis
(3, 'S Corporations', 'What is the effect of an additional cash contribution by a shareholder to an S corporation?', '["It increases the shareholder''s stock basis by the amount contributed", "It increases the shareholder''s debt basis by the amount contributed", "It has no effect on shareholder basis until the corporation uses the cash", "It increases the accumulated adjustments account by the amount contributed"]'::jsonb, 0, 'Under IRC Section 1367, a shareholder''s stock basis increases when the shareholder makes additional capital contributions to the S corporation. Cash contributions increase stock basis dollar for dollar. Debt basis is created only by direct loans from the shareholder to the corporation, not capital contributions. AAA tracks income and deduction items, not capital contributions.', 'easy', 1),

-- Q9: medium / L2 — Section 1244 ordinary loss on S corp stock
(3, 'S Corporations', 'Kimball paid $60,000 for stock in Westgate Corp, a qualifying small business corporation that elected S status. Westgate becomes insolvent and Kimball, a single filer, sells the worthless stock for $0 in 2026. Under Section 1244, how is Kimball''s $60,000 loss treated?', '["$60,000 long-term capital loss", "$60,000 short-term capital loss", "$10,000 ordinary loss and $50,000 capital loss", "$50,000 ordinary loss and $10,000 capital loss"]'::jsonb, 3, 'Under IRC Section 1244, an individual shareholder of a qualifying small business corporation may claim an ordinary loss deduction of up to $50,000 ($100,000 if married filing jointly) on the disposition of Section 1244 stock. Kimball''s $60,000 loss is split: $50,000 ordinary loss and $10,000 capital loss. This benefit applies regardless of whether the corporation has elected S corporation status.', 'medium', 2),

-- Q10: easy / L1 — Shareholders pay estimated taxes on pass-through income
(3, 'S Corporations', 'Who is responsible for making estimated tax payments on S corporation pass-through income?', '["The S corporation pays estimated taxes on behalf of shareholders", "Each shareholder makes estimated tax payments on their individual returns", "The S corporation and shareholders split the estimated tax obligation equally", "No estimated taxes are required because the income is reported annually"]'::jsonb, 1, 'Under IRC Section 6654, individual shareholders are responsible for making estimated tax payments on their share of S corporation pass-through income. The S corporation itself generally does not pay federal income tax except for the built-in gains tax and excess net passive income tax. Shareholders must include their Schedule K-1 income when calculating quarterly estimated payments.', 'easy', 1),

-- Q11: medium / L2 — Rental income separately stated on K-1
(3, 'S Corporations', 'Ridgeway Corp, an S corporation, earns $180,000 of consulting revenue and $30,000 of net rental income from a commercial property it owns. On each shareholder''s Schedule K-1, how are these two items reported?', '["Both are combined and reported as $210,000 of ordinary business income", "The consulting revenue is ordinary business income; the rental income is reported as tax-exempt income", "The consulting revenue is ordinary business income; the rental income is separately stated as net rental real estate income", "Both are separately stated as distinct income items on the K-1"]'::jsonb, 2, 'Under IRC Section 1366(a), rental income is a separately stated item on Schedule K-1 because it may be subject to the passive activity loss rules at the shareholder level under Section 469. The consulting revenue is part of nonseparately stated ordinary business income. Combining them would prevent shareholders from properly applying their individual passive activity limitations.', 'medium', 2),

-- Q12: medium / L3 — Section 267 related party loss disallowance
(3, 'S Corporations', 'Atlas Corp, an S corporation, sells equipment with a $70,000 adjusted basis to its sole shareholder, Grayson, for $50,000 (fair market value). Under IRC Section 267, how is the $20,000 loss treated?', '["The loss is fully deductible by Atlas Corp and passes through to Grayson", "The loss is deductible by Atlas Corp but cannot be claimed by Grayson on his return", "The loss is deferred until Grayson sells the equipment to an unrelated party", "The $20,000 loss is disallowed and does not pass through to Grayson"]'::jsonb, 3, 'Under IRC Section 267(a)(1) and (b)(2), losses on sales between an S corporation and a shareholder who owns more than 50% of the stock are disallowed. Grayson owns 100%, triggering the related-party loss disallowance rule. The loss does not pass through to the shareholder. However, under Section 267(d), Grayson may offset gain on a subsequent sale of the equipment by the disallowed loss amount.', 'medium', 3),

-- Q13: medium / L2 — Late S election relief under Rev. Proc. 2013-30
(3, 'S Corporations', 'Pinnacle Services Corp intended to elect S corporation status effective January 1, 2026, but failed to file Form 2553 until September 30, 2026. The corporation had reasonable cause for the delay and all shareholders consented. What relief is potentially available?', '["No relief is available; the election is effective January 1, 2027", "The corporation can file an amended Form 1120 to convert retroactively", "The IRS may grant relief only if the delay was fewer than 60 days", "The IRS may grant late election relief under Rev. Proc. 2013-30, making the election effective January 1, 2026"]'::jsonb, 3, 'Under Rev. Proc. 2013-30, the IRS may grant late S corporation election relief if the entity had reasonable cause for the late filing, all shareholders consented, and the entity otherwise met all eligibility requirements from the intended effective date. If granted, the election is retroactive to January 1, 2026. Without this relief, the default rule under Section 1362(b)(3) would make the election effective January 1, 2027.', 'medium', 2),

-- Q14: hard / L3 — AAA can go negative from losses but distributions cannot reduce AAA below zero
(3, 'S Corporations', 'Whitaker Corp, an S corporation with accumulated C corporation E&P of $50,000, begins 2026 with AAA of $40,000. During 2026, Whitaker reports a $70,000 ordinary loss and distributes $20,000 to its sole shareholder before year-end. What is the ending AAA balance?', '["Negative $30,000, because the $70,000 loss reduces AAA after adjusting for the distribution", "Negative $50,000, because both the distribution and loss reduce AAA without limitation", "$0, because AAA cannot be reduced below zero", "$20,000, because the loss is limited to the pre-distribution AAA balance"]'::jsonb, 0, 'Under Reg. 1.1368-2(a)(3), AAA is first adjusted for income and loss items before distributions are taken into account. The $70,000 loss reduces the $40,000 AAA to negative $30,000. Distributions cannot reduce AAA below zero, but AAA is already negative from losses, so the $20,000 distribution does not further reduce it. Unlike shareholder stock basis (which floors at zero), AAA can go negative from losses and deductions.', 'hard', 3),

-- Q15: medium / L2 — Rents with substantial services excluded from passive investment income
(3, 'S Corporations', 'Hargrove Corp, an S corporation with accumulated C corporation E&P, earns $300,000 of gross receipts: $200,000 from property management services and $100,000 from rents on properties where Hargrove provides cleaning, security, and maintenance to tenants. For the Section 1375 excess net passive income test, how much is passive investment income?', '["$300,000, because all income involves real property", "$200,000, because only the management fee income is passive", "$100,000, because rental income is always passive investment income", "$0, because rents where the corporation renders significant services are excluded"]'::jsonb, 3, 'Under IRC Section 1362(d)(3)(C)(i) and Reg. 1.1362-2(c)(5)(ii)(B)(2), rents are excluded from passive investment income when the corporation renders significant services to tenants (cleaning, security, maintenance). The management fee income is active income by nature. Hargrove has $0 passive investment income, so the Section 1375 tax does not apply. Without the significant services exception, the $100,000 in rents would be counted as passive.', 'medium', 2),

-- Q16: hard / L4 — S corp inheriting E&P via Section 381 acquisition
(3, 'S Corporations', 'Archer Corp, an S corporation that has never been a C corporation, acquires all assets of Vanguard Corp, a C corporation with accumulated E&P of $200,000, in a tax-free Type A reorganization. After the acquisition, Archer continues as an S corporation. Evaluate the consequences of inheriting Vanguard''s accumulated E&P.', '["Archer''s S election automatically terminates because S corporations cannot have accumulated E&P", "Archer inherits the $200,000 E&P under Section 381, subjecting it to the Section 1375 excess net passive income tax risk if passive income exceeds 25% of gross receipts", "The $200,000 E&P is eliminated upon the acquisition because the acquiring entity is an S corporation", "Archer inherits the E&P but it is immediately distributed tax-free to shareholders"]'::jsonb, 1, 'Under IRC Section 381(c)(2), the acquiring corporation in a tax-free reorganization inherits the target''s accumulated E&P. An S corporation can carry accumulated E&P from acquisitions even if it was never a C corporation itself. This exposes Archer to the Section 1375 excess net passive income tax and the three-year termination rule under Section 1362(d)(3). Inheriting E&P does not itself terminate the S election — it merely creates exposure.', 'hard', 4),

-- Q17: hard / L4 — Installment sale pass-through to shareholders
(3, 'S Corporations', 'Meridian Corp, an S corporation with two equal shareholders, sells land (basis $100,000) for $400,000, receiving $100,000 down and a $300,000 installment note. Meridian elects the installment method under Section 453. In Year 1, only the $100,000 down payment is received. Evaluate how the gain is reported to shareholders.', '["The full $300,000 gain is recognized in Year 1 and split $150,000 per shareholder", "Each shareholder reports $50,000 of gain in Year 1, with no further gain until the note is paid in full", "Each shareholder reports $37,500 of gain in Year 1, with remaining gain recognized as installment payments are received", "The S corporation pays entity-level tax on $75,000 and passes through the remaining $225,000"]'::jsonb, 2, 'Under IRC Section 453 and Section 1366, the installment method passes through to shareholders. The gross profit percentage is 75% ($300,000 gain / $400,000 price). The $100,000 payment yields $75,000 of recognized gain ($100,000 x 75%), split equally as $37,500 per shareholder. Remaining gain is recognized as future payments are received. The $150,000 answer incorrectly recognizes all gain at closing rather than ratably under the installment method.', 'hard', 4),

-- Q18: easy / L2 — Loss character passes through unchanged
(3, 'S Corporations', 'Pinecrest Corp, an S corporation, recognizes a $15,000 long-term capital loss from selling investment securities during 2026. How does this loss pass through to shareholders?', '["As an ordinary loss deduction on each shareholder''s K-1", "As a short-term capital loss on each shareholder''s K-1", "As a reduction to the corporation''s accumulated adjustments account only", "As a long-term capital loss on each shareholder''s K-1"]'::jsonb, 3, 'Under IRC Section 1366(b), the character of items passed through to S corporation shareholders is determined at the entity level. A long-term capital loss recognized by the S corporation retains its long-term character and passes through on Schedule K-1. The shareholder then applies it against capital gains and the $3,000 annual capital loss limitation on their individual return. The loss does not convert to ordinary or short-term character.', 'easy', 2),

-- Q19: medium / L2 — BIG tax reduces pass-through gain to shareholders
(3, 'S Corporations', 'Granite Corp, a former C corporation that elected S status two years ago, sells a built-in gain asset and incurs $42,000 of Section 1374 built-in gains tax at the entity level. How does this entity-level tax affect the income passing through to shareholders?', '["The pass-through gain is reduced by the $42,000 BIG tax, so shareholders report less income", "Shareholders report the full gain; the $42,000 is treated as a nondeductible expense reducing basis", "The $42,000 is deducted as a corporate expense on Form 1120-S, increasing ordinary loss", "Shareholders receive a tax credit of $42,000 to offset double taxation"]'::jsonb, 0, 'Under IRC Section 1366(f)(2), the Section 1374 built-in gains tax paid at the entity level reduces the amount of gain that passes through to shareholders on their Schedule K-1. This mechanism prevents full double taxation — the corporation pays tax on the built-in gain, and shareholders report only the net amount. The BIG tax is not treated as a nondeductible expense or a shareholder-level tax credit.', 'medium', 2),

-- Q20: medium / L2 — S corp not eligible for dividends received deduction
(3, 'S Corporations', 'Belmont Corp, an S corporation, receives $50,000 of dividend income from a 30%-owned domestic corporation during 2026. Can Belmont claim a dividends received deduction (DRD) on this income?', '["Yes, Belmont may deduct 65% of the dividends under Section 243", "Yes, Belmont may deduct 50% of the dividends under Section 243", "Yes, but only if Belmont has accumulated C corporation E&P", "No, S corporations are not eligible for the dividends received deduction"]'::jsonb, 3, 'Under IRC Section 1363(b)(2), an S corporation computes its taxable income in the same manner as an individual, not a C corporation. Since the dividends received deduction under Section 243 is available only to C corporations, S corporations cannot claim it. Instead, the dividend income passes through to shareholders on Schedule K-1 and is reported on their individual returns, potentially as qualified dividend income.', 'medium', 2),

-- Q21: medium / L3 — Sale after 5-year BIG recognition period — no tax
(3, 'S Corporations', 'Sterling Corp converted from C to S corporation status on January 1, 2020, with an asset having a basis of $80,000 and FMV of $200,000 at conversion. Sterling sells the asset for $220,000 on March 1, 2026. What is the Section 1374 built-in gains tax on the sale?', '["$25,200, calculated as 21% of the $120,000 built-in gain at conversion", "$0, because the sale occurred after the five-year recognition period expired", "$29,400, calculated as 21% of the total $140,000 gain", "$4,200, calculated as 21% of the $20,000 post-conversion appreciation only"]'::jsonb, 1, 'Under IRC Section 1374(d)(7), the built-in gains tax applies only to gains recognized during the five-year recognition period following conversion from C to S status. Sterling elected S status on January 1, 2020, so the recognition period ended December 31, 2024. Because the sale occurred on March 1, 2026 — after the five-year window — no Section 1374 tax applies. The full $140,000 gain passes through to shareholders tax-free at the entity level.', 'medium', 3),

-- Q22: medium / L3 — Section 179 deduction reduces shareholder basis
(3, 'S Corporations', 'Oakdale Corp, an S corporation, elects a $120,000 Section 179 deduction for qualifying equipment in 2026 and passes the deduction through to its sole shareholder, Harris, who has $200,000 stock basis. After Harris claims the Section 179 deduction on her individual return, what is the effect on her stock basis?', '["No effect — the Section 179 deduction does not reduce shareholder basis", "Basis decreases by $60,000, representing half of the Section 179 amount", "Basis decreases by $120,000 to $80,000", "Basis decreases by $120,000 only if Harris also reduces her individual Section 179 limitation"]'::jsonb, 2, 'Under IRC Section 1367(a)(2)(B), deductible losses and deductions passed through from the S corporation reduce the shareholder''s stock basis, including the Section 179 deduction. Harris''s stock basis decreases by the full $120,000 from $200,000 to $80,000. The Section 179 deduction is treated like any other deduction for basis adjustment purposes, preventing the shareholder from deducting the same economic cost twice through a later stock sale.', 'medium', 3),

-- Q23: hard / L4 — Complex basis ordering with income, tax-exempt, distribution, nondeductible expense, and loss
(3, 'S Corporations', 'Jennings, the sole shareholder of Hillcrest Corp (an S corporation), begins 2026 with stock basis of $45,000. During 2026, Hillcrest reports $30,000 ordinary income, $5,000 tax-exempt interest, a $60,000 cash distribution, an $8,000 nondeductible fine, and a $25,000 ordinary loss. Evaluate Jennings''s ending stock basis after applying the correct ordering rules.', '["$2,000 with no suspended loss", "$0 with $12,000 suspended loss", "$0 with $13,000 suspended loss", "$12,000 with no suspended loss"]'::jsonb, 2, 'Under IRC Section 1367, basis adjustments follow strict ordering: (1) increase for income ($30,000) and tax-exempt income ($5,000) to $80,000; (2) decrease for distributions ($60,000) to $20,000; (3) decrease for nondeductible expenses ($8,000) to $12,000; (4) decrease for deductible losses ($25,000 limited to remaining $12,000) to $0, suspending $13,000. The $12,000 suspended answer miscalculates the nondeductible expense step; the $12,000 basis answer ignores the loss entirely.', 'hard', 4),

-- Q24: easy / L1 — S corp distributions not subject to FICA/SE tax
(3, 'S Corporations', 'How are S corporation distributions to shareholders treated for employment tax purposes?', '["Distributions are not subject to FICA or self-employment tax", "Distributions are subject to FICA tax at the same rate as wages", "Distributions are subject to self-employment tax like partnership distributions to general partners", "Distributions are subject to the 0.9% Additional Medicare Tax only"]'::jsonb, 0, 'Under IRC Section 1402(a), S corporation distributions are not subject to FICA or self-employment tax. Unlike general partners, S corporation shareholders do not pay self-employment tax on pass-through income or distributions. However, shareholder-employees must receive reasonable compensation as W-2 wages subject to FICA before taking distributions — a key compliance issue under IRS audit guidelines.', 'easy', 1),

-- Q25: easy / L1 — Two short-year returns on mid-year S election termination
(3, 'S Corporations', 'When an S corporation election terminates mid-year, what returns must the corporation file for that year?', '["One Form 1120-S for the full year with an attached statement", "Two separate returns: a short-year Form 1120-S and a short-year Form 1120", "One Form 1120 for the full year treating it as a C corporation", "One Form 1120-S for the full year with the C corporation income reported on Schedule K"]'::jsonb, 1, 'Under IRC Section 1362(e)(1), when an S election terminates mid-year, the tax year is divided into an S short year and a C short year. The corporation files a short-period Form 1120-S for the S portion and a short-period Form 1120 for the C portion. Each return covers only its respective period. Filing a single return for the full year would improperly combine pass-through and entity-level taxation.', 'easy', 1),

-- Q26: easy / L1 — Community property spouse must consent to S election
(3, 'S Corporations', 'In a community property state, who must consent to the S corporation election on Form 2553?', '["Only the shareholder of record", "Only the shareholder and the corporation''s officers", "Both the shareholder and the shareholder''s spouse if the stock is community property", "All employees and officers of the corporation"]'::jsonb, 2, 'Under IRC Section 1362(a)(2) and Reg. 1.1362-6(b)(2)(i), in community property states, the shareholder''s spouse is treated as a co-owner of the stock and must also consent to the S election on Form 2553. Failure to obtain spousal consent can invalidate the election entirely. In non-community property states, only the shareholders of record must consent to the election.', 'easy', 1),

-- Q27: medium / L3 — Section 1245 depreciation recapture character passes through
(3, 'S Corporations', 'Ashford Corp, an S corporation, sells fully depreciated office equipment (original cost $45,000, accumulated depreciation $45,000, adjusted basis $0) for $30,000. How should Ashford characterize the $30,000 gain for pass-through to shareholders?', '["$30,000 of ordinary income under Section 1245 depreciation recapture", "$30,000 of Section 1231 gain", "$30,000 of long-term capital gain", "$15,000 of ordinary income and $15,000 of Section 1231 gain"]'::jsonb, 0, 'Under IRC Section 1245, gain on the sale of depreciable personal property is recaptured as ordinary income to the extent of accumulated depreciation. Ashford claimed $45,000 of depreciation, and the $30,000 gain is entirely within the recapture amount, so the full gain is ordinary income. This character passes through to shareholders under Section 1366(b). Section 1231 gain would apply only to the extent gain exceeds total depreciation recapture.', 'medium', 3),

-- Q28: easy / L1 — Testamentary trust eligible for two years
(3, 'S Corporations', 'For how long after receiving S corporation stock may a testamentary trust remain an eligible S corporation shareholder?', '["Indefinitely, as long as the trust has only U.S. individual beneficiaries", "Two years from the date the stock is transferred to the trust", "One year from the date of the decedent''s death", "Five years from the date of the decedent''s death"]'::jsonb, 1, 'Under IRC Section 1361(c)(2)(A)(iii), a testamentary trust that receives S corporation stock under a will is an eligible shareholder for the two-year period beginning on the date the stock is transferred to the trust. After this period, the trust must convert to a qualifying trust type (such as a QSST or ESBT) or distribute the stock to an eligible shareholder to preserve the S election.', 'easy', 1),

-- Q29: medium / L3 — Pass-through income increases basis even without distributions (phantom income)
(3, 'S Corporations', 'Barrett is the sole shareholder of Dawson Corp, an S corporation that reports $120,000 of ordinary income for 2026 but makes no distributions. Barrett''s beginning stock basis is $50,000. Barrett asks whether his basis changes even though he received no cash. What is Barrett''s ending stock basis?', '["$50,000, because basis changes only when distributions are received", "$170,000, because pass-through income increases stock basis regardless of distributions", "$120,000, because the income replaces the original basis", "$50,000, because the income is not taxable until distributed"]'::jsonb, 1, 'Under IRC Section 1367(a)(1), a shareholder''s stock basis increases by their pro rata share of all S corporation income items, regardless of whether cash is distributed. Barrett''s basis increases from $50,000 to $170,000. This ''phantom income'' concept means shareholders are taxed on and receive basis credit for pass-through income even without receiving cash, which preserves basis for future tax-free distributions or loss deductions.', 'medium', 3),

-- Q30: easy / L1 — S corp cannot join consolidated return
(3, 'S Corporations', 'Can an S corporation join in filing a consolidated federal income tax return with affiliated C corporations?', '["No, an S corporation cannot be included in a consolidated return", "Yes, if the S corporation owns 80% or more of the subsidiary", "Yes, but only with other S corporations in the affiliated group", "Yes, if the parent corporation is a C corporation"]'::jsonb, 0, 'Under IRC Section 1504(b)(8), an S corporation is excluded from the definition of an includible corporation and therefore cannot join in filing a consolidated return under Section 1501. This applies regardless of the ownership structure. If a corporation wants to participate in consolidated filing, it must be a C corporation. An S corporation may own a qualified Subchapter S subsidiary (QSub) under Section 1361(b)(3), but that is not a consolidated return.', 'easy', 1)
;

COMMIT;
